const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let saved={};try{saved=JSON.parse(localStorage.getItem('thai-sprout-v1')||'{}')}catch{}
let state={lang:saved.lang==='zh'?'zh':'en',chapter:Math.max(0,Math.min(3,Number(saved.chapter)||0)),id:letters.some(l=>l.id===saved.id)?saved.id:1,tab:'learn',stage:'trace',library:false,explorer:false,completed:false};
let progress=saved.progress||{}, strokesById={}, currentStroke=null, pen='#647d4b', meta={}, demoFrame=0,demoTime=0,demoPlaying=true,slow=true,artPlaying=!matchMedia('(prefers-reduced-motion: reduce)').matches,artTime=0,quiz=null,recording=null;
const t=(en,zh)=>state.lang==='zh'?zh:en;
const L=()=>letters.find(l=>l.id===state.id), C=()=>chapters[state.chapter];
const sprout=`<svg viewBox="0 0 80 80" fill="none" aria-hidden="true"><path d="M40 66V35" stroke="#65794a" stroke-width="4" stroke-linecap="round"/><path d="M40 44Q13 44 16 18Q42 17 40 44" fill="#a8bd70"/><path d="M40 35Q40 10 67 12Q66 36 40 35" fill="#6d8952"/><path d="M20 66H60L55 76H26Z" fill="#d4c7a9"/></svg>`;
const soundIcon='↗';
const done=id=>Boolean(progress[id]?.heard&&progress[id]?.wrote&&progress[id]?.quiz);
const starterIds=chapters.flatMap(c=>c.ids);
function persist(){try{localStorage.setItem('thai-sprout-v1',JSON.stringify({...state,progress}))}catch{toast(t('Progress could not be saved on this browser.','這個瀏覽器無法儲存進度。'))}}
function mark(key){progress[state.id]={...progress[state.id],[key]:true};persist();updateProgress()}
function updateProgress(){let n=starterIds.filter(done).length;let el=$('#garden-count');if(el)el.textContent=`${n} / 16 ${t('letters grown','個字母完成')}`;let bar=$('#growth');if(bar)bar.style.width=`${n/16*100}%`}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function stopSound(){if(recording){recording.pause();recording=null}if('speechSynthesis'in window)speechSynthesis.cancel()}
function recorded(id=state.id){stopSound();recording=new Audio(`assets/letter-${id}.mp3`);recording.play().then(()=>{if(id===state.id)mark('heard');toast(t('Playing Thai: ','正在播放泰語：')+letters[id-1].char+' '+letters[id-1].word)}).catch(()=>toast(t('Tap again to play the recording. Check your volume.','請再點一次播放，並確認音量。')))}
let voices=[];function refreshVoices(){voices=window.speechSynthesis?.getVoices()||[]}refreshVoices();if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',refreshVoices);
function speak(text,lang){stopSound();if(!('speechSynthesis'in window)){toast(t('Speech is unavailable in this browser. Read the explanation below.','此瀏覽器不支援語音，請閱讀文字解說。'));return}refreshVoices();let v=voices.find(v=>v.lang.toLowerCase().startsWith(lang));if(lang==='th'&&!v){recorded();toast(t('Playing the recorded Thai letter name with its word.','播放泰語字母名稱與對應詞的錄音。'));return}let u=new SpeechSynthesisUtterance(text);u.lang=lang==='th'?'th-TH':'en-US';if(v)u.voice=v;u.rate=lang==='th'?.72:.86;u.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')toast(t('Voice unavailable. Please check your device’s speech voices.','語音無法播放，請檢查裝置語音設定。'))};speechSynthesis.speak(u)}
function english(){const l=L();speak(`This Thai letter has the picture word ${l.en}. Listen to the Thai recording for the letter name. At the start of a syllable, it makes ${l.sound}. ${l.tip} Now try it with your finger.`,'en')}
function goLetter(id,explorer=false){stopSound();state.id=id;state.explorer=explorer;state.library=false;state.completed=false;state.tab='learn';state.stage='trace';demoFrame=0;demoTime=0;demoPlaying=true;quiz=null;persist();render()}
function render(){const l=L(),c=C(),n=starterIds.filter(done).length;$('#app').innerHTML=`
 <header><div class="brand">${sprout}<div><strong>thai sprout<span style="color:#8a9f63">.</span></strong><small>LITTLE LETTERS, BIG ADVENTURES</small></div></div><div class="header-right"><span class="eyebrow">GROW A LITTLE EVERY DAY</span><div class="lang" role="group" aria-label="Hint language"><button data-lang="en" class="${state.lang==='en'?'selected':''}" aria-pressed="${state.lang==='en'}">English</button><button data-lang="zh" class="${state.lang==='zh'?'selected':''}" aria-pressed="${state.lang==='zh'}">中文提示</button></div><button class="icon-btn" id="help-btn" aria-label="${t('Grown-up guide','家長指南')}">?</button></div></header>
 <div class="layout"><aside><div class="journey-title"><span class="eyebrow">${t('MY LEARNING PATH','我的學習路線')}</span><span style="color:#a2ac83">✧</span></div>${chapters.map((ch,i)=>`<button class="chapter ${state.chapter===i&&!state.explorer?'current':''}" data-chapter="${i}"><span class="num">${ch.icon}</span><span><strong>${t(ch.name,ch.zh)}</strong><small>${t('4 letters · one little adventure','4 個字母・一次小冒險')}</small><span class="tiny-dots">${ch.ids.map(id=>`<i class="${done(id)?'done':''}"></i>`).join('')}</span></span></button>`).join('')}<div class="library-button"><button id="library-btn">▦ &nbsp; ${t('Explore all 44 letters','探索全部 44 個字母')} &nbsp; ↗</button></div><div class="garden">${sprout}<h4>${t('Your little letter garden','你的小小字母花園')}</h4><p>${t('Listen, write and play.<br>Watch your learning grow.','聽一聽、寫一寫、玩一玩。<br>每天進步一點點。')}</p><div class="meter"><i id="growth" style="width:${n/16*100}%"></i></div><small id="garden-count" style="font-size:10px;color:#7c806c">${n} / 16 ${t('letters grown','個字母完成')}</small></div><div class="sidebar-foot">${t('Made for curious little minds.<br>Ages 6–8 · Learn at your own pace.','為好奇的小朋友而設計。<br>6–8 歲・按自己的步調學習。')}</div></aside>
 <main><div class="welcome"><div><div class="eyebrow">${t('A LITTLE THAI, A LITTLE EVERY DAY','每天學一點泰文')}</div><h1>${t('Small steps. Big adventures.','小小一步，大大冒險。')}</h1><p>${t('Listen to a letter. Make a new friend. Try it with your own hand.','聽聽字母的聲音，認識新朋友，再用小手寫寫看。')}</p></div><div class="daily">☀ &nbsp; ${t('5–10 happy minutes','每天開心學 5–10 分鐘')}</div></div>
 <div class="lesson-meta"><span><strong>${state.explorer?t('LETTER EXPLORER','字母探索家'):t(`CHAPTER 0${state.chapter+1}`,`第 ${state.chapter+1} 章`)}</strong> &nbsp; / &nbsp; ${state.explorer?t('Find a new favorite', '找到新朋友'):t(c.name,c.zh)}</span><div class="letter-strip">${(state.explorer?[state.id]:c.ids).map(id=>`<button class="letter-pick thai ${state.id===id?'active':''}" data-letter="${id}" aria-label="${letters[id-1].char} ${letters[id-1].en}" aria-pressed="${id===state.id}">${letters[id-1].char}${done(id)?'<span class="check">✓</span>':''}</button>`).join('')}</div></div>
 <section class="workspace" aria-label="${t('Letter lesson','字母課程')}">${state.library?libraryHTML():state.completed?completeHTML():`<nav class="tabs" aria-label="Learning activity">${[['learn','Listen & look','聽聲音，看圖像'],['write','Watch & write','看示範，動手寫'],['play','Play & remember','玩遊戲，記起來']].map(([key,en,zh],i)=>`<button class="tab ${state.tab===key?'active':''}" data-tab="${key}" aria-pressed="${state.tab===key}"><span class="step">${i+1}</span>${t(en,zh)}</button>`).join('')}</nav><div id="activity">${state.tab==='learn'?learnHTML():state.tab==='write'?writeHTML():quizHTML()}</div><div class="lesson-footer"><div class="footer-copy"><b>${t('A little practice is a big step.','小小練習，就是大大進步。')}</b>${state.tab==='write'?t('No perfect letters needed. Just give it a try!','不必寫得完美，勇敢試試看！'):t('Listen → watch → try → play','聽一聽 → 看一看 → 寫一寫 → 玩一玩')}</div><button class="primary" id="next-btn">${state.tab==='learn'?t('Let’s write it','來寫寫看'):state.tab==='write'?t('Let’s play','來玩遊戲'):t('Next little adventure','下一個小冒險')} <span>→</span></button></div>`}</section>
 <div class="bottom-tip"><span>✦</span><span>${t('Little learner tip: say it out loud, draw it in the air, then try it on the screen.','小秘訣：大聲說一次，在空中畫一次，再在螢幕上寫一次。')}</span></div>${state.explorer&&!state.library?`<button class="secondary back-library" id="back-library">← ${t('All 44 letters','全部 44 個字母')}</button>`:''}</main></div>`;
 bind();if(state.tab==='write'&&!state.library&&!state.completed){setupPad();loadDemo()}if(state.tab==='play'&&!state.library&&!state.completed)bindQuiz();
}
function learnHTML(){let l=L();return `<div class="lesson-grid"><div class="picture-side"><div class="card-kicker"><span>${t('MEET YOUR LETTER FRIEND','認識你的字母朋友')}</span><span class="pill">${t('Tap & listen','點一下，聽聲音')}</span></div><button class="art-controls" id="art-toggle" aria-label="${t('Pause or play picture animation','暫停或播放圖片動畫')}" aria-pressed="${artPlaying}">${artPlaying?'Ⅱ':'▶'}</button><div class="scene">${artSVG(l.art)}</div><div class="word-label"><div><h2 class="thai" lang="th">${l.word}</h2><p>${l.en}${state.lang==='zh'?' · '+l.zh:''}</p></div><button class="round-sound" id="word-audio" aria-label="${t('Hear the Thai word','聆聽泰語詞彙')}">♫</button></div></div><div class="content-side"><span class="eyebrow">${t('HELLO! I’M YOUR NEW LETTER','你好！我是你的新字母')}</span><div class="letter-display"><div class="big-letter thai" lang="th">${l.char}</div><div><h2 class="letter-name thai" lang="th">${l.char} ${l.word}</h2><p class="roman">${l.roman}</p><span class="sound-tag">${t('THAI CONSONANT','泰文子音')}</span></div></div><p class="explain">${t(`Meet <b>${l.char}</b>! Its picture word is <b>${l.en}</b>.<br>At the start of a syllable: ${l.sound}.`,`認識 <b>${l.char}</b>！它的圖像詞是<b>「${l.zh}」</b>。<br>音節開頭的發音：${l.soundZh}。`)}</p><div class="audio-actions"><button class="primary" id="letter-audio">♫ &nbsp; ${t('Hear Thai','聽泰語')}</button><button class="secondary" id="english-audio">▷ &nbsp; ${t('Explain in English','英文語音解說')}</button></div><div class="hint">✧ &nbsp; ${t('Your turn! Listen, then say the letter name together. The small English letters are only a sound guide.','換你了！先聽，再一起說字母名稱。羅馬字只是輔助，發音請跟著泰語錄音。')}${[3,5].includes(l.id)?'<br>'+t('Explorer note: this letter is no longer used in everyday spelling.','探索提醒：這個字母已不再用於日常拼寫。'):''}</div></div></div>`}
function writeHTML(){let l=L();return `<div class="write-grid"><div class="demo-box"><h3>${t('1. Watch the line','1. 看線條怎麼走')}</h3><canvas class="demo-canvas" id="demo" width="156" height="186" aria-label="${l.char} writing animation"></canvas><div class="demo-buttons"><button id="replay">↻ ${t('Replay','重播')}</button><button id="demo-toggle">${demoPlaying?'Ⅱ':'▶'}</button><button id="speed" aria-pressed="${slow}">${slow?'0.5×':'1×'}</button></div><p>${t(l.tip,l.tipZh)}</p><p style="font-size:9px">${t('Writing model: NIU SEAsite','書寫示範：NIU SEAsite')}</p></div><div><div class="stages" aria-label="Writing mode">${[['trace','2. Trace','2. 描一描'],['copy','3. Copy','3. 照著寫'],['free','4. On my own','4. 自己寫']].map(([k,en,zh])=>`<button data-stage="${k}" class="${state.stage===k?'active':''}" aria-pressed="${state.stage===k}">${t(en,zh)}</button>`).join('')}</div><div class="pad-wrap"><canvas id="pad" aria-label="${t('Handwriting area. Draw with a finger, Apple Pencil or mouse.','手寫區：可用手指、Apple Pencil 或滑鼠書寫。')}"></canvas><span class="pad-label">${t('YOUR LITTLE WRITING SPACE','你的小小手寫天地')} · ${L().char}</span></div><div class="pad-tools"><div class="pen-colors" aria-label="Pen color">${[['#647d4b','Green'],['#8b78a9','Purple'],['#c88462','Orange']].map(([color,name])=>`<button data-color="${color}" style="background:${color}" class="${pen===color?'selected':''}" aria-label="${name} pen" aria-pressed="${pen===color}"></button>`).join('')}</div><div class="tool-buttons"><button id="undo">↶ ${t('Undo','復原')}</button><button id="clear">${t('Clear','清除')}</button><button id="save-drawing">↓ ${t('Save','儲存')}</button></div></div><p class="write-note">${t('Use your finger or Apple Pencil. Follow the writing demo for direction; the pale letter is a shape guide. Practice stays here when you change tabs.','用手指或 Apple Pencil 書寫。方向請跟隨左側示範；淡色字形供描寫。切換分頁仍保留筆跡。')}</p></div></div>`}
function makeQuiz(){let choices=(state.explorer?letters.map(l=>l.id):C().ids).filter(id=>id!==state.id).sort(()=>Math.random()-.5).slice(0,3);choices.push(state.id);quiz={id:state.id,choices:choices.sort(()=>Math.random()-.5),solved:false}}
function quizHTML(){if(!quiz||quiz.id!==state.id)makeQuiz();return `<div class="quiz"><span class="eyebrow">${t('A LITTLE MEMORY GAME','小小記憶遊戲')}</span><h2>${t(`Which letter goes with ${L().en}?`,`哪個字母配「${L().zh}」？`)}</h2><div class="quiz-visual">${artSVG(L().art)}</div><button class="soft" id="quiz-audio">♫ ${t('Listen to the clue','聽聽提示')}</button><div class="answers">${quiz.choices.map(id=>`<button class="thai ${quiz.solved&&id===state.id?'correct':''}" data-answer="${id}" aria-label="${letters[id-1].char}">${letters[id-1].char}</button>`).join('')}</div><div class="feedback" id="feedback" role="status">${quiz.solved?t('You found it! Lovely remembering.','找到了！記得真清楚。'):t('Tap a letter. Take your time.','點選一個字母，慢慢來。')}</div></div>`}
function libraryHTML(){return `<div class="library"><span class="eyebrow">${t('THE WHOLE LETTER GARDEN','完整的字母花園')}</span><h2>${t('44 letters. So much to discover.','44 個字母，等你來發現。')}</h2><p>${t('Start with the 16 letters in our four chapters. When you feel ready, tap any letter here to listen, watch it being written, and practice.','先學四個章節裡的 16 個字母。準備好了，就點選這裡的任何字母，聽發音、看示範並練習書寫。')}</p><div class="alphabet-grid">${letters.map(l=>`<button data-explore="${l.id}" class="${[3,5].includes(l.id)?'obsolete':''}"><strong class="thai">${l.char}</strong><small>${t(l.en,l.zh)}${[3,5].includes(l.id)?' *':''}</small></button>`).join('')}</div><p>${t('* ฃ and ฅ are historical letters, rarely used today. This is a consonant introduction; vowels, tone rules and reading words come later.','* ฃ 和 ฅ 是現今已不再常用的歷史字母。這是子音入門課；母音、聲調規則與拼讀將是後續學習內容。')}</p></div>`}
function completeHTML(){let count=C().ids.filter(done).length;return `<div class="completion">${sprout}<div class="eyebrow">${t('ONE LITTLE ADVENTURE FINISHED','完成一次小冒險')}</div><h2>${t('Look how much you’ve grown!','看看你進步了多少！')}</h2><p>${t(`You explored four letters. ${count} of 4 have listening, writing and a correct match.<br>Try saying them once more, then take a little stretch.`,`你已探索四個字母，其中 ${count} 個完成聽音、手寫及配對。<br>再說一次，然後起來伸個懶腰吧！`)}</p><div class="letter-strip" style="justify-content:center">${C().ids.map(id=>`<button class="letter-pick thai" data-letter="${id}">${letters[id-1].char}</button>`).join('')}</div><button class="primary" id="continue-chapter">${state.chapter<3?t('Explore the next chapter','探索下一章'):t('Explore all 44 letters','探索全部 44 個字母')} →</button></div>`}
function bind(){
 $$('[data-lang]').forEach(b=>b.onclick=()=>{state.lang=b.dataset.lang;document.documentElement.lang=state.lang==='zh'?'zh-Hant':'en';persist();render()});
 $$('[data-chapter]').forEach(b=>b.onclick=()=>{state.chapter=+b.dataset.chapter;goLetter(C().ids.find(id=>!done(id))||C().ids[0])});
 $$('[data-letter]').forEach(b=>b.onclick=()=>goLetter(+b.dataset.letter,state.explorer));
 $$('[data-tab]').forEach(b=>b.onclick=()=>{stopSound();state.tab=b.dataset.tab;render()});
 $$('[data-stage]').forEach(b=>b.onclick=()=>{state.stage=b.dataset.stage;render()});
 $$('[data-explore]').forEach(b=>b.onclick=()=>goLetter(+b.dataset.explore,true));
 $$('[data-color]').forEach(b=>b.onclick=()=>{pen=b.dataset.color;$$('[data-color]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)})});
 const on=(id,fn)=>{let e=$('#'+id);if(e)e.onclick=fn};
 on('library-btn',()=>{stopSound();state.library=true;state.explorer=true;render()});on('back-library',()=>{state.library=true;render()});on('help-btn',help);
 on('letter-audio',()=>recorded());on('english-audio',english);on('word-audio',()=>speak(L().word,'th'));on('art-toggle',()=>{artPlaying=!artPlaying;$('#art-toggle').textContent=artPlaying?'Ⅱ':'▶';$('#art-toggle').setAttribute('aria-pressed',artPlaying)});
 on('next-btn',()=>{stopSound();if(state.tab==='learn')state.tab='write';else if(state.tab==='write'){if(!(strokesById[state.id]||[]).some(s=>s.points.length>4)){toast(t('Try drawing your letter first. You can also tap Play above.','先試著寫寫字母，也可以點上方遊戲分頁。'));return}state.tab='play'}else{if(!quiz?.solved){toast(t('Find the matching letter first. You can change lessons any time above.','先找出配對字母；也可隨時從上方切換課程。'));return}if(state.explorer){goLetter(state.id%44+1,true);return}let i=C().ids.indexOf(state.id);if(i<3){goLetter(C().ids[i+1]);return}state.completed=true}render()});
 on('continue-chapter',()=>{if(state.chapter<3){state.chapter++;goLetter(C().ids[0])}else{state.library=true;state.explorer=true;render()}});
 on('undo',()=>{(strokesById[state.id]||[]).pop();drawPad()});on('clear',()=>{strokesById[state.id]=[];drawPad()});on('save-drawing',saveDrawing);
 on('replay',()=>{demoFrame=0;demoTime=0;demoPlaying=true;$('#demo-toggle').textContent='Ⅱ';paintDemo()});on('demo-toggle',()=>{demoPlaying=!demoPlaying;$('#demo-toggle').textContent=demoPlaying?'Ⅱ':'▶'});on('speed',()=>{slow=!slow;$('#speed').textContent=slow?'0.5×':'1×';$('#speed').setAttribute('aria-pressed',slow)});
}
function bindQuiz(){$('#quiz-audio').onclick=()=>recorded();$$('[data-answer]').forEach(b=>b.onclick=()=>{if(quiz.solved)return;if(+b.dataset.answer===state.id){quiz.solved=true;mark('quiz');b.classList.add('correct');$('#feedback').textContent=t('You found it! Lovely remembering.','找到了！記得真清楚。')}else{b.classList.add('wrong');$('#feedback').textContent=t('A good try! Listen once more, then pick another letter.','很棒的嘗試！再聽一次，然後選另一個字母。');setTimeout(()=>b.classList.remove('wrong'),750)}})}
let padSize={w:0,h:0},padObserver=null;
function setupPad(){padObserver?.disconnect();let canvas=$('#pad');strokesById[state.id]??=[];const resize=()=>{let r=canvas.getBoundingClientRect();padSize={w:r.width,h:r.height};const d=devicePixelRatio||1;canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);drawPad()};padObserver=new ResizeObserver(resize);padObserver.observe(canvas);resize();let pointer=null;
 const point=e=>{let r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}};
 canvas.onpointerdown=e=>{if(pointer!==null)return;e.preventDefault();pointer=e.pointerId;canvas.setPointerCapture(pointer);currentStroke={color:pen,points:[point(e)]};strokesById[state.id].push(currentStroke);drawPad()};
 canvas.onpointermove=e=>{if(e.pointerId!==pointer||!currentStroke)return;e.preventDefault();for(const p of e.getCoalescedEvents?.()||[e])currentStroke.points.push(point(p));drawPad()};
 const end=e=>{if(e.pointerId!==pointer)return;if(currentStroke?.points.length>4)mark('wrote');pointer=null;currentStroke=null};canvas.onpointerup=end;canvas.onpointercancel=end;canvas.onlostpointercapture=end;
}
function drawPad(){let canvas=$('#pad');if(!canvas)return;let {w,h}=padSize;if(!w||!h)return;let ctx=canvas.getContext('2d'),d=devicePixelRatio||1;ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle='#fffefa';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#e5e8dc';ctx.lineWidth=1;ctx.setLineDash([5,7]);for(let y of [.22,.50,.78]){ctx.beginPath();ctx.moveTo(0,h*y);ctx.lineTo(w,h*y);ctx.stroke()}ctx.beginPath();ctx.moveTo(w*.5,0);ctx.lineTo(w*.5,h);ctx.stroke();ctx.setLineDash([]);if(state.stage==='trace'){ctx.fillStyle='#e8ecdf';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`500 ${h*.72}px "Noto Sans Thai", Tahoma, sans-serif`;ctx.fillText(L().char,w*.5,h*.50)}if(state.stage==='copy'){ctx.fillStyle='#a3ad91';ctx.font=`500 ${h*.19}px "Noto Sans Thai", Tahoma, sans-serif`;ctx.textAlign='left';ctx.textBaseline='top';ctx.fillText(L().char,14,10)}for(let s of strokesById[state.id]||[]){ctx.strokeStyle=s.color;ctx.lineWidth=Math.max(4,w*.014);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();s.points.forEach((p,i)=>i?ctx.lineTo(p.x*w,p.y*h):ctx.moveTo(p.x*w,p.y*h));if(s.points.length===1){ctx.lineTo(s.points[0].x*w+.1,s.points[0].y*h)}ctx.stroke()}}
function saveDrawing(){const src=$('#pad');if(!src)return;let out=document.createElement('canvas');out.width=src.width;out.height=src.height+100;let ctx=out.getContext('2d');ctx.fillStyle='#fffefa';ctx.fillRect(0,0,out.width,out.height);ctx.drawImage(src,0,80);ctx.fillStyle='#536b3d';ctx.font='30px sans-serif';ctx.fillText(`Thai Sprout · ${L().char} ${L().word}`,24,48);out.toBlob(blob=>{let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`my-thai-letter-${state.id}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast(t('Your writing picture is ready to save.','你的手寫圖片已準備好儲存。'))},'image/png')}
let demoImage=null,demoId=null;
function loadDemo(){if(!meta[state.id])return;demoId=state.id;demoImage=new Image();demoImage.onload=paintDemo;demoImage.src=`assets/writing-${state.id}.png`}
function paintDemo(){let canvas=$('#demo'),m=meta[state.id];if(!canvas||!m||!demoImage?.complete||demoId!==state.id)return;let ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);let s=Math.min(canvas.width/m.width,canvas.height/m.height),w=m.width*s,h=m.height*s;ctx.drawImage(demoImage,(demoFrame%m.frames)*m.width,0,m.width,m.height,(canvas.width-w)/2,(canvas.height-h)/2,w,h)}
let prev=0;function tick(now){let dt=Math.min(100,now-prev);prev=now;if(!document.hidden){if(artPlaying){artTime+=dt;$$('.art-character').forEach(g=>{let a=artTime/800;g.setAttribute('transform',`translate(0 ${Math.sin(a)*3.5}) rotate(${Math.sin(a*.7)*1.4} 160 180)`)})}let m=meta[state.id];if($('#demo')&&m&&demoPlaying){demoTime+=dt;let duration=(m.durations[demoFrame]||100)*(slow?2:1);if(demoTime>=duration){demoTime=0;demoFrame=(demoFrame+1)%m.frames;paintDemo()}}}requestAnimationFrame(tick)}
function help(){let d=$('#help');d.innerHTML=`<div class="help-top"><h2>${t('A note for grown-ups','給家長的小筆記')}</h2><button class="icon-btn" id="close-help" aria-label="Close">×</button></div><h3>${t('A gentle learning rhythm','循序漸進的小節奏')}</h3><p>${t('Begin with one letter, for 5–10 minutes. Listen and repeat, draw in the air, watch the writing model, trace, copy, then try from memory. The four starter chapters introduce 16 consonants. The explorer includes all 44.','每次先學一個字母，練習 5–10 分鐘。先聽再模仿，在空中畫，觀察書寫示範，再描寫、照寫及憑記憶書寫。四個入門章節包含 16 個子音，探索區提供全部 44 個子音。')}</p><h3>${t('Sound and handwriting','發音與書寫')}</h3><p>${t('Hear Thai plays a recorded letter name and associated word from Northern Illinois University SEAsite. The word button uses a Thai device voice when available; otherwise it plays the full recorded name and word. English explanations use your device’s speech voice. On iPad, tap a sound button first and check media volume. You may need to add a Thai voice in iPad speech settings.','「聽泰語」播放北伊利諾大學 SEAsite 的字母名稱與對應詞錄音。詞彙按鈕優先使用裝置的泰語語音；若沒有，則播放完整的字母與詞彙錄音。英文解說使用裝置語音。iPad 請先點播放並確認媒體音量，必要時在 iPad 語音設定加入泰語。')}</p><p>${t('Romanization is approximate. Sound hints describe the beginning of a syllable, not final consonants or tone rules. Picture words help name a letter; the letter is not always the first character of that word. The pale tracing glyph is a shape guide. Use the animated writing model for direction. We record participation, not handwriting accuracy.','羅馬字只供輔助。發音提示只說明音節開頭，不涵蓋尾音或聲調規則。圖像詞用於命名字母，目標字母不一定是該詞第一個字。淡色字形供描寫，書寫方向請參照動畫。本網站記錄練習參與，不評分筆跡是否正確。')}</p><h3>${t('Progress on this iPad','這台 iPad 的學習紀錄')}</h3><p>${t('Listening, drawing and a correct match grow one letter in the garden. Progress is saved only in this browser. Handwriting remains during this visit; use Save to keep a PNG. Refreshing clears the drawings. No account or child information is requested by this learning app. This learning website is public; no ChatGPT sign-in is needed.','完成聽音、手寫與正確配對，花園就會多一個字母。進度只儲存在這個瀏覽器。筆跡保留至本次瀏覽結束，可用「儲存」下載 PNG；重新整理會清除筆跡。學習程式不要求孩子註冊或提供個人資料；這是公開學習網站，不需要登入 ChatGPT。')}</p><h3>${t('Learning sources','教學資料來源')}</h3><p><a href="https://seasite.niu.edu/Thai/basic/alpha_cons_table.htm" target="_blank" rel="noopener">Northern Illinois University · SEAsite Thai consonants</a><br>${t('Letter-name recordings and animated writing models are credited to NIU SEAsite. Vocabulary scenes for the starter lessons are original SVG illustrations animated in JavaScript. Explorer scenes also use device emoji.','字母名稱錄音與書寫動畫來源：NIU SEAsite。入門課的詞彙圖是原創 SVG 插圖，以 JavaScript 驅動動畫；探索區也使用裝置表情符號圖像。')}</p><button class="secondary" id="reset-progress">${t('Reset learning progress…','重設學習進度…')}</button>`;$('#close-help').onclick=()=>d.close();$('#reset-progress').onclick=()=>{if(confirm(t('Clear the learning progress stored in this browser?','要清除此瀏覽器儲存的學習進度嗎？'))){progress={};persist();d.close();render()}};d.showModal()}
fetch('assets/writing.json').then(r=>r.json()).then(data=>{meta=data;if($('#demo'))loadDemo()}).catch(()=>toast(t('Writing models could not load. Please reload when connected.','書寫示範無法載入，請連線後重新整理。')));
document.fonts?.ready.then(()=>drawPad());document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSound()});document.documentElement.lang=state.lang==='zh'?'zh-Hant':'en';render();requestAnimationFrame(tick);
